const incomingItems = $input.all();
const historyRows = incomingItems
  .map(item => item.json)
  .filter(row => row && !row.error && (row.content || row.created_at || row.timestamp || row.role));

if (historyRows.length === 0) {
  return { json: { formatted_history: [] } };
}

const sorted = historyRows.sort((a, b) => {
  const ta = new Date(a.created_at || a.timestamp || 0).getTime();
  const tb = new Date(b.created_at || b.timestamp || 0).getTime();
  return ta - tb;
});

const formattedHistory = sorted
  .slice(-20)
  .map(msg => ({
    role: msg.role === "assistant" ? "assistant" : "user",
    content: String(msg.content || "")
  }))
  .filter(msg => msg.content.trim() !== "");

return {
  json: {
    formatted_history: formattedHistory
  }
};

const userMsg = String($('Normalize Incoming Message').first().json.userMessage || '').toLowerCase();

const intents = {
  price:     /harga|biaya|bayar|berapa|paket|daftar|join|member|membership|promo|diskon/.test(userMsg),
  class:     /kelas|jadwal|program|olahraga|latihan|yoga|strength|pilates|fitdance|boxing|trampoline|aerobic/.test(userMsg),
  coach:     /coach|pelatih|trainer|instruktur|komunitas|teman|support/.test(userMsg),
  location:  /lokasi|alamat|dimana|di mana|maps|google map|parkir|fasilitas|tempat|kepanjen|malang/.test(userMsg),
  challenge: /21 hari|21 days|challenge|meal plan|nutrisi|diet/.test(userMsg),
  goals:     /target|goals|turun|naik|berat|langsing|fit|sehat|percaya diri/.test(userMsg),
};

const categoryMap = {
  price:     ['harga_pembayaran', 'pendaftaran'],
  class:     ['kelas_program'],
  coach:     ['coach_community'],
  location:  ['lokasi_fasilitas'],
  challenge: ['challenge_21_days'],
  goals:     ['goals_transformasi', 'target_member'],
};

const matchedCategories = new Set(['tentang_stepup', 'faq_umum']);
for (const [intent, active] of Object.entries(intents)) {
  if (active && categoryMap[intent]) categoryMap[intent].forEach(c => matchedCategories.add(c));
}

const allKb = $('Fetch Knowledge Base').all()
  .map(d => d.json)
  .filter(row => row && (row.description || row.content || row.category || row.intent_name));

const filteredKb = allKb.filter(row => matchedCategories.has(row.category));
const kbItems = (filteredKb.length ? filteredKb : allKb.slice(0, 5))
  .map(row => ({ json: { ...row, _source: 'kb' } }));

// === INJECT DATA SHEET ASLI (anti-halusinasi) ===
const sheetItems = [];

if (intents.price || intents.challenge) {
  const hargaRows = $('Fetch Sheet Harga').all().map(d => d.json).filter(r => r && r.nama_paket);
  for (const row of hargaRows) {
    sheetItems.push({
      json: {
        _source: 'sheet_harga',
        category: 'harga_pembayaran',
        content: [
          `Nama Paket: ${row.nama_paket}`,
          `Kategori: ${row.kategori || ''}`,
          `Harga: ${row.harga}`,
          `Durasi: ${row.durasi || ''}`,
          `Fasilitas: ${row.fasilitas_utama || ''}`,
          row.ketentuan ? `Ketentuan: ${row.ketentuan}` : '',
          row.cocok_untuk ? `Cocok Untuk: ${row.cocok_untuk}` : '',
        ].filter(Boolean).join(' | '),
      }
    });
  }
  const promoRows = $('Fetch Sheet Promo').all().map(d => d.json).filter(r => r && r.nama_promo && r.status === 'active');
  for (const row of promoRows) {
    sheetItems.push({
      json: {
        _source: 'sheet_promo',
        category: 'harga_pembayaran',
        content: [`Promo: ${row.nama_promo}`, `Diskon: ${row.diskon || ''}`, row.syarat ? `Syarat: ${row.syarat}` : ''].filter(Boolean).join(' | '),
      }
    });
  }
}

if (intents.class) {
  const rows = $('Fetch Sheet Jadwal').all().map(d => d.json).filter(r => r && r.nama_kelas);
  for (const row of rows) {
    sheetItems.push({ json: { _source: 'sheet_jadwal', category: 'kelas_program', content: [`Kelas: ${row.nama_kelas}`, row.hari ? `Hari: ${row.hari}` : '', row.jam ? `Jam: ${row.jam}` : '', row.coach ? `Coach: ${row.coach}` : ''].filter(Boolean).join(' | ') } });
  }
}

if (intents.coach) {
  const rows = $('Fetch Sheet Coach').all().map(d => d.json).filter(r => r && r.nama_coach);
  for (const row of rows) {
    sheetItems.push({ json: { _source: 'sheet_coach', category: 'coach_community', content: [`Coach: ${row.nama_coach}`, `Specialist: ${row.specialist || ''}`, `Mengajar: ${row.hari_mengajar || ''}`].join(' | ') } });
  }
}

// Sheet items DULUAN — LLM baca data authoritative sebelum KB
return [...sheetItems, ...kbItems];

function safeGet(nodeName) {
  try {
    return $(nodeName).all().map(d => d.json).filter(row => row && !row.error && Object.keys(row).length > 0);
  } catch (e) { return []; }
}

const rawUserMsg = String($('Normalize Incoming Message').first().json.userMessage || '');
const userMsg = rawUserMsg.toLowerCase();

// === WAKTU SEKARANG (Jakarta) ===
const nowJkt = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Jakarta' }));
const dayNames = ['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
const currentDayName = dayNames[nowJkt.getDay()];
const currentHour = nowJkt.getHours();
const currentTimeStr = nowJkt.toTimeString().slice(0,5) + ' WIB';
const greetingTime = currentHour < 11 ? 'pagi' : currentHour < 15 ? 'siang' : currentHour < 18 ? 'sore' : 'malam';

// Deteksi "hari ini" → ganti ke nama hari sekarang
const resolvedUserMsg = userMsg
  .replace(/\bhari ini\b/g, currentDayName.toLowerCase())
  .replace(/\bsekarang\b(?=.*jadwal)/g, currentDayName.toLowerCase());

const mentionsToday = /hari ini|sekarang|today/.test(userMsg);

// === DATA DIAMBIL LEBIH AWAL (sebelum dipakai untuk deteksi) ===
function isActive(row) {
  const s = String(row.status || row.Status || '').toLowerCase();
  return !s || s === 'aktif' || s === 'active';
}

const allHarga  = safeGet('Fetch Sheet Harga').filter(isActive);
const allJadwal = safeGet('Fetch Sheet Jadwal').filter(isActive);
const allCoachRaw = safeGet('Fetch Sheet Coach').filter(isActive);

// === DETEKSI INTENT ===
const isPureGreeting = /^(halo|hallo|hello|hi|hey|pagi|siang|sore|malam|assalamualaikum|wa'alaikum|waalaikum|selamat pagi|selamat siang|selamat sore|selamat malam|hai|hei|hoi|oi|assalam|waalaikumsalam|السلام|permisi|excuse me)[\s!.,]*$/i.test(rawUserMsg.trim());
const wantsFullList    = /semua|lengkap|full|list|daftar lengkap|jadwal lengkap|paket lengkap/.test(userMsg);
const asksLocation     = /alamat|lokasi|dimana|di mana|maps|google map|tempatnya/.test(userMsg);
const asksPrice        = /harga|biaya|berapa|paket|member|membership|promo|diskon|trial|free/.test(userMsg);
const asksSchedule     = /jadwal|jam|hari|kapan|senin|selasa|rabu|kamis|jumat|jum'at|sabtu|minggu/.test(userMsg);
const asksCoach        = /coach|pelatih|trainer|instruktur|pengajar|guru/.test(userMsg);
const asksEvent        = /event|acara|challenge/.test(userMsg);
const asksPromo        = /promo|diskon|trial|free/.test(userMsg);
const hasSpecificDay   = /senin|selasa|rabu|kamis|jumat|jum'at|sabtu|minggu/.test(resolvedUserMsg) || mentionsToday;

const jadwalClassNames = [...new Set(allJadwal.map(r => String(r.kelas || '').toLowerCase()).filter(Boolean))];
const mentionedClass   = jadwalClassNames.find(cls => userMsg.includes(cls));
const asksClass        = !!mentionedClass || /kelas|class/.test(userMsg);

const packageNames     = [...new Set(allHarga.map(r => String(r.nama_paket || '').toLowerCase()).filter(Boolean))];
const mentionedPackage = packageNames.find(pkg => userMsg.includes(pkg)) || null;

const asksClassAndPrice = (asksClass || !!mentionedClass) && asksPrice;
const asksOnlyGeneralPrice = asksPrice && !mentionedPackage && !/(private|vip|challenge|21 hari|bulanan|bulan|harian|perdatang|trial|special|online|pengelolaan|berat badan|turbo|reguler)/.test(userMsg);

let answerMode = 'GENERAL';
if (asksLocation)                          answerMode = 'LOCATION';
else if (asksClassAndPrice)                answerMode = 'CLASS_AND_PRICE';
else if (asksPrice && asksOnlyGeneralPrice) answerMode = 'PRICE_GENERAL_CLARIFY';
else if (asksPrice)                        answerMode = 'PRICE_SPECIFIC';
else if (asksSchedule && hasSpecificDay)   answerMode = 'SCHEDULE_SPECIFIC_DAY';
else if (asksSchedule)                     answerMode = 'SCHEDULE_GENERAL';
else if (asksClass)                        answerMode = 'CLASS_GENERAL';

// === HELPERS ===
function compactRow(row, keys) {
  return keys.map(k => row[k] ? `${k}: ${row[k]}` : '').filter(Boolean).join(' | ');
}

function formatRows(rows, keys) {
  return rows.filter(isActive).map(r => compactRow(r, keys)).filter(Boolean).join('\n');
}

function unique(rows, key) {
  return [...new Set(rows.map(r => String(r[key] || '').trim()).filter(Boolean))];
}

function rupiahNumber(v) { const n = Number(String(v||'').replace(/\D/g,'')); return isFinite(n) && n > 0 ? n : null; }
function rupiahFormat(n) { return 'Rp' + Number(n).toLocaleString('id-ID'); }

// === KB ===
let kb = safeGet('Filter KB By Intent').filter(r => !r._source || r._source === 'kb');

if (asksLocation) {
  const locKb = kb.filter(r => {
    const intent = String(r.intent_name||'').toLowerCase();
    const cat = String(r.category||'').toLowerCase();
    const txt = String(r.description||r.content||'').toLowerCase();
    return cat==='lokasi_fasilitas' || intent.includes('alamat') || txt.includes('alamat lengkap');
  });
  kb = [...locKb, ...kb.filter(r => !locKb.some(l => l.id===r.id))];
}
kb = kb.slice(0, wantsFullList ? 12 : (asksLocation ? 8 : 5));

// === DATA SLICES ===
const promo = (asksPromo||asksPrice) ? safeGet('Fetch Sheet Promo').filter(isActive).slice(0,5) : [];
const harga = asksPrice ? allHarga.slice(0, wantsFullList ? 30 : 15) : [];

// === JADWAL FILTER ===
let jadwalToShow = allJadwal;
let filteringDebug = { searched: null, found: null, error: null };

if (hasSpecificDay) {
  const dayRegex = /senin|selasa|rabu|kamis|jumat|jum'at|sabtu|minggu/i;
  const dayMatch = (resolvedUserMsg || userMsg).match(dayRegex);

  if (dayMatch) {
    const targetDay = dayMatch[0].toLowerCase().replace(/jum'at/i, 'jumat');
    filteringDebug.searched = targetDay;

    const filtered = allJadwal.filter(r => String(r.hari || '').trim().toLowerCase() === targetDay);
    filteringDebug.found = filtered.length;

    if (filtered.length === 0) {
      const availableDays = [...new Set(allJadwal.map(r => String(r.hari || '').trim()))];
      filteringDebug.error = `No schedule for "${targetDay}". Available: ${availableDays.join(', ')}`;
    } else {
      jadwalToShow = filtered;
    }
  }
}

// === COACH FILTER ===
let coachToShow = allCoachRaw;

if (asksCoach) {
  const classKeyword = allCoachRaw
    .flatMap(c => (c.specialist||'').split(',').map(s => s.trim()))
    .find(cls => cls && userMsg.includes(cls.toLowerCase()));

  if (classKeyword) {
    const filtered = allCoachRaw.filter(c => String(c.specialist||'').toLowerCase().includes(classKeyword.toLowerCase()));
    if (filtered.length > 0) coachToShow = filtered;
  }
}

const coach = asksCoach ? coachToShow : [];
const event = asksEvent ? safeGet('Fetch Sheet Event').filter(isActive).slice(0,5) : [];

// === JOIN JADWAL + COACH ===
const coachMap = {};
allCoachRaw.forEach(c => {
  const name = String(c.nama_coach || '').trim().toLowerCase();
  if (name) coachMap[name] = c;
});

const jadwalJoined = jadwalToShow.map(j => {
  const coachName = String(j.coach || '').trim();
  const coachData = coachMap[coachName.toLowerCase()];
  if (coachData) {
    const specialist = coachData.specialist ? ` [${coachData.specialist}]` : '';
    return { ...j, coach: coachName + specialist };
  }
  return j;
});

const jadwal = (asksSchedule||asksClass) ? jadwalJoined.slice(0, wantsFullList ? 50 : 30) : [];

// === SUMMARY DATA ===
const classNames      = unique(allJadwal, 'kelas');
const priceCategories = unique(allHarga, 'kategori');
const numericPrices   = allHarga.map(r => rupiahNumber(r.harga)).filter(Boolean);
const minPrice        = numericPrices.length ? Math.min(...numericPrices) : null;
const maxPrice        = numericPrices.length ? Math.max(...numericPrices) : null;
const priceRangeText  = minPrice && maxPrice ? `${rupiahFormat(minPrice)} sampai ${rupiahFormat(maxPrice)}` : '';
const locationText    = asksLocation
  ? kb.map(r=>r.description||r.content||'').find(t=>/alamat lengkap|Jl\.|Kepanjen|Malang/i.test(t)) || '' : '';
const kbText = kb.map(r=>r.description||r.content||'').filter(Boolean).join('\n');

// === COMPOSE OUTPUT ===
const parts = [];
parts.push(`=== WAKTU SEKARANG ===\nHari: ${currentDayName}\nJam: ${currentTimeStr}\nSapaan: selamat ${greetingTime}`);

if (classNames.length)      parts.push(`=== RINGKASAN NAMA KELAS ===\n${classNames.join(', ')}`);
if (priceCategories.length) parts.push(`=== KATEGORI HARGA TERSEDIA ===\n${priceCategories.join(', ')}`);
if (locationText)           parts.push(`=== ALAMAT STEPUP ===\n${locationText}`);
if (kbText)                 parts.push(`=== KNOWLEDGE BASE RINGKAS ===\n${kbText}`);
if (promo.length)  parts.push(`=== PROMO AKTIF ===\n${formatRows(promo,  ['nama_promo','deskripsi_promo','harga','benefit','periode'])}`);
if (harga.length)  parts.push(`=== HARGA & PAKET ===\n${formatRows(harga, ['nama_paket','kategori','harga','durasi','fasilitas_utama','ketentuan','cocok_untuk'])}`);
if (jadwal.length) parts.push(`=== JADWAL/KELAS ===\n${formatRows(jadwal, ['hari','jam','kelas','coach'])}`);
if (coach.length)  parts.push(`=== DATA COACH ===\n${formatRows(coach,  ['nama_coach','specialist','hari_mengajar'])}`);
if (event.length)  parts.push(`=== EVENT ===\n${formatRows(event,  ['nama_event','deskripsi','tanggal','harga','lokasi'])}`);

const msg = $('Normalize Incoming Message').first().json;
const finalUserMessage = isPureGreeting ? rawUserMsg + ' (selamat ' + greetingTime + ')' : rawUserMsg;

return { json: {
  dataContext: parts.join('\n\n') || 'Tidak ada data referensi.',
  answerMode: isPureGreeting ? 'GREETING' : answerMode,
  locationText, priceRangeText, hasSpecificDay,
  asksOnlyGeneralPrice, asksClassAndPrice,
  isPureGreeting, currentDayName, greetingTime,
  chat_id: msg.chat_id, whatsapp_number: msg.whatsapp_number,
  client_id: msg.client_id, session_name: msg.session_name,
  timestamp: msg.timestamp, userMessage: rawUserMsg,
  resolvedUserMessage: isPureGreeting ? rawUserMsg : resolvedUserMsg,
  filteringDebug,
  jadwalFilteredCount: jadwal.length,
  coachCount: coach.length,
  answerModeDetermined: answerMode
}};

const item = $input.first().json;
const fallbackReply = 'Maaf Kak, sistem kami sedang agak sibuk. Coba kirim ulang pesan Kakak beberapa saat lagi ya.';

const rawReply = String(
  item.output?.[0]?.content?.[0]?.text ||
