).trim();

function humanClean(text) {
  let out = String(text || '')
    .replace(/\[INTENT:JOIN\]/g, ' [INTENT:JOIN] ')
    .replace(/^#{1,6}\s*/gm, '')
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/\*(.*?)\*/g, '$1')
    .replace(/__(.*?)__/g, '$1')
    .replace(/_(.*?)_/g, '$1')
    .replace(/[ \t]+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  const bannedCta = /(jika|kalau).*(tertarik|membutuhkan|butuh|ingin tahu|info lebih lanjut)|silakan\s+(tanya|hubungi)|langsung\s+tanya|beritahu\s+ya|kami\s+siap\s+membantu/i;
  out = out
    .split('\n')
    .map(line => line.trim())
    .filter(line => line && !bannedCta.test(line))
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  return out;
}

function classifyJoinIntent(userText, modelText) {
  const msg = String(userText || '').toLowerCase();
  const modelMarkedJoin = String(modelText || '').includes('[INTENT:JOIN]');
  const asksInfo = /(apa saja|apa aja|harga|berapa|biaya|promo|free trial|trial|kelas|program|jadwal|jam|hari|kapan|lokasi|alamat|dimana|fasilitas|coach|special class|\?)/i.test(msg);
  const explicitJoin = /(mau|ingin|pengen|boleh|bisa|gas|lanjut|daftar|join|booking|ambil|ikut|isi form|formulir|member|membership|paket)\s*(daftar|join|booking|ambil|ikut|member|membership|paket|kelas|trial|sekarang|hari ini|besok)?/i.test(msg);
  const clearCommand = /(saya|aku|sy|aq)\s*(mau|ingin|pengen)\s*(daftar|join|booking|ambil|ikut)|^(daftar|join|booking|ambil paket|mau daftar|mau join)\b/i.test(msg);
  return modelMarkedJoin && (clearCommand || (explicitJoin && !asksInfo));
}

const ctx = $('Build Human WhatsApp Context').first().json;
